/**
 * Wallrus Provider - browse wallpapers generated by the Wallrus app.
 *
 * Wallrus (https://github.com/megakode/wallrus) is a GTK4 app that generates
 * abstract wallpapers using shaders and exports them as PNG/JPEG images.
 * By default, exported images go to the user's Pictures folder with names
 * like "wallrus_bars_*.png".
 *
 * This provider searches for Wallrus-generated images in:
 * - Default: `~/Pictures/Wallrus` (if it exists) or `~/Pictures` filtered by prefix
 * - Extra folders from 'wallrus-folders' GSettings key (colon-separated)
 * - Optional recursive search controlled by 'wallrus-recursive'
 *
 * No API key, no network. Results are sorted by modification time (newest first).
 */

import Gio from 'gi://Gio';
import GLib from 'gi://GLib';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const IMAGE_EXTENSIONS = [
    'jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp',
    'tif', 'tiff', 'svg', 'avif', 'jxl', 'heic', 'heif',
];
const MAX_DEPTH = 8;
const MAX_FILES = 10000;
const DEFAULT_PER_PAGE = 24;
const WALLRUS_FILENAME_PREFIX = 'wallrus_';

/**
 * Default Pictures folder, or empty string when unavailable.
 *
 * @returns {string}
 */
export function getDefaultPicturesDir() {
    const dir = GLib.get_user_special_dir(GLib.UserDirectory.DIRECTORY_PICTURES);
    return dir || '';
}

// ---------------------------------------------------------------------------
// WallrusProvider
// ---------------------------------------------------------------------------

export class WallrusProvider {
    static displayName = 'Wallrus';
    static requiresApiKey = false;
    static websiteUrl = 'https://github.com/megakode/wallrus';
    static keyHelpUrl = '';

    constructor() {}

    /**
     * Configured when at least one search folder exists and contains images.
     *
     * @param {Gio.Settings} [settings]  Extension GSettings instance.
     * @returns {boolean}
     */
    isConfigured(settings = null) {
        try {
            const folders = this._resolveFolders(settings).filter(f => {
                try {
                    return f.query_exists(null);
                } catch (_skip) {
                    return false;
                }
            });
            return folders.length > 0;
        } catch (_skip) {
            return false;
        }
    }

    /**
     * Search Wallrus-generated images.
     *
     * @param {{q?: string, page?: number, perPage?: number}} params
     * @param {Soup.Session} [session]   Unused (no network).
     * @param {Gio.Settings} [settings]  Reads wallrus-folders / wallrus-recursive.
     * @returns {Promise<{items: Array, total: number, page: number, lastPage: number}>}
     */
    async search({q = '', page = 1, perPage = DEFAULT_PER_PAGE} = {}, session = null, settings = null) {
        const folders = this._resolveFolders(settings).filter(f => {
            try {
                return f.query_exists(null);
            } catch (_skip) {
                return false;
            }
        });

        if (!folders.length)
            throw new Error('Wallrus: no folders found. Check the Providers settings.');

        let recursive = true;
        try {
            recursive = settings ? settings.get_boolean('wallrus-recursive') : true;
        } catch (_skip) {
            recursive = true;
        }

        const collected = [];
        for (const folder of folders)
            this._walk(folder, recursive, 0, collected);

        const needle = q.trim().toLowerCase();
        let matched = needle
            ? collected.filter(f => f.name.toLowerCase().includes(needle))
            : collected;

        // Prefer wallrus-named files when no explicit query
        if (!needle) {
            matched = matched.filter(f => f.name.toLowerCase().startsWith(WALLRUS_FILENAME_PREFIX));
        }

        matched.sort((a, b) => b.mtime - a.mtime);

        const total = matched.length;
        const safePerPage = Math.max(1, perPage);
        const lastPage = Math.max(1, Math.ceil(total / safePerPage));
        const safePage = Math.min(Math.max(1, page), lastPage);
        const slice = matched.slice((safePage - 1) * safePerPage, safePage * safePerPage);

        return {items: slice.map(_normalize), total, page: safePage, lastPage};
    }

    // -----------------------------------------------------------------------
    // Folder resolution
    // -----------------------------------------------------------------------

    /**
     * Default Pictures/Wallrus folder plus configured extras, deduplicated.
     *
     * @param {Gio.Settings} [settings]
     * @returns {Gio.File[]}
     * @private
     */
    _resolveFolders(settings) {
        const paths = [];
        const pictures = getDefaultPicturesDir();
        if (pictures) {
            const wallrusDir = GLib.build_filenamev([pictures, 'Wallrus']);
            // Default to Wallrus subfolder; if it doesn't exist, fall back to Pictures but filter
            paths.push(wallrusDir);
            paths.push(pictures);
        }

        try {
            const extras = settings ? settings.get_strv('wallrus-folders') : [];
            for (const p of extras) {
                const trimmed = (p || '').trim();
                if (trimmed)
                    paths.push(trimmed);
            }
        } catch (_skip) {
            // Missing key (older schema) — defaults only.
        }

        const seen = new Set();
        const folders = [];
        for (const p of paths) {
            if (seen.has(p))
                continue;
            seen.add(p);
            folders.push(Gio.File.new_for_path(p));
        }
        return folders;
    }

    // -----------------------------------------------------------------------
    // Recursive walk
    // -----------------------------------------------------------------------

    /**
     * Walk a folder collecting image files.
     *
     * @param {Gio.File} dir        Folder to scan.
     * @param {boolean} recursive   Descend into subfolders.
     * @param {number} depth        Current depth (capped).
     * @param {Array} out           Collector.
     * @private
     */
    _walk(dir, recursive, depth, out) {
        if (depth > MAX_DEPTH || out.length >= MAX_FILES)
            return;

        let enumerator = null;
        try {
            enumerator = dir.enumerate_children(
                'standard::name,standard::type,time::modified',
                Gio.FileQueryInfoFlags.NOFOLLOW_SYMLINKS, null);
        } catch (_skip) {
            return;
        }

        try {
            let info = null;
            while (out.length < MAX_FILES && (info = enumerator.next_file(null)) !== null) {
                const name = info.get_name();
                if (name.startsWith('.'))
                    continue;
                const child = enumerator.get_child(info);
                const ftype = info.get_file_type();
                if (ftype === Gio.FileType.DIRECTORY) {
                    if (recursive)
                        this._walk(child, recursive, depth + 1, out);
                } else if (ftype === Gio.FileType.REGULAR && _isImage(name)) {
                    out.push({
                        uri: child.get_uri(),
                        name,
                        mtime: info.get_attribute_uint64('time::modified'),
                        folder: dir.get_basename(),
                    });
                }
            }
        } catch (_skip) {
            // Unreadable entries are skipped.
        } finally {
            try {
                enumerator.close(null);
            } catch (_skip) {
                // Nothing to release.
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Module helpers
// ---------------------------------------------------------------------------

function _isImage(name) {
    const dot = name.lastIndexOf('.');
    if (dot < 0)
        return false;
    return IMAGE_EXTENSIONS.includes(name.slice(dot + 1).toLowerCase());
}

function _normalize(file) {
    return {
        id: GLib.compute_checksum_for_string(GLib.ChecksumType.MD5, file.uri, -1),
        previewUrl: file.uri,
        fullUrl: file.uri,
        resolution: '',
        source: 'Wallrus',
        sourceUrl: file.uri,
        tags: file.folder || '',
    };
}
